module asyn_fifo(
    input wclk, input rclk, input wrstn, input rrstn, input winc, input rinc, 
    input [WIDTH-1:0] wdata,
    output wfull, output rempty, output [WIDTH-1:0] rdata
);
// Parameters
parameter WIDTH = 8;
parameter DEPTH = 16;
localparam ADDR_WIDTH = $clog2(DEPTH);
// Internal wires and registers
reg [WIDTH-1:0] ram_data[0:DEPTH-1];
integer i;
reg [ADDR_WIDTH:0] waddr_bin, raddr_bin, wptr, rptr;
reg [ADDR_WIDTH:0] wptr_buff, rptr_buff;
reg [ADDR_WIDTH:0] wptr_syn, rptr_syn;
reg wen, ren;
wire [ADDR_WIDTH:0] wptr_gray, rptr_gray;
// Convert bin to gray code
function [ADDR_WIDTH:0] bin2gray(input [ADDR_WIDTH:0] bin);
    begin
        bin2gray = bin ^ (bin >> 1);
    end
endfunction
// Convert gray code to bin
function [ADDR_WIDTH:0] gray2bin(input [ADDR_WIDTH:0] gray);
    reg [ADDR_WIDTH:0] bin;
    integer i;
    begin
        bin[ADDR_WIDTH] = gray[ADDR_WIDTH];
        for(i = ADDR_WIDTH-1; i >= 0; i = i - 1)
            bin[i] = bin[i+1] ^ gray[i];
        gray2bin = bin;
    end
endfunction
// Dual-port RAM
generate
    genvar idx;
    for(idx = 0; idx < DEPTH; idx = idx + 1) begin
        always@(posedge wclk or negedge wrstn) begin
            if(!wrstn)
                ram_data[idx] <= {WIDTH{1'b0}};
            else if((idx==waddr_bin)&&(winc))
                ram_data[idx] <= wdata;
        end
    end
endgenerate
assign rdata = ram_data[raddr_bin];
// Write pointer
always@(posedge wclk or negedge wrstn) begin
    if(!wrstn)
        waddr_bin <= {(ADDR_WIDTH+1){1'b0}};
    else if(winc)
        waddr_bin <= waddr_bin + {{ADDR_WIDTH{1'b0}}, 1'b1};
end
assign wptr_gray = bin2gray(waddr_bin);
always@(posedge wclk or negedge wrstn) begin
    if(!wrstn)
        wptr <= {(ADDR_WIDTH+1){1'b0}};
    else
        wptr <= wptr_gray;
end
always@(posedge wclk or negedge wrstn) begin
    if(!wrstn)
        wptr_buff <= {(ADDR_WIDTH+1){1'b0}};
    else
        wptr_buff <= wptr;
end
always@(posedge rclk or negedge rrstn) begin
    if(!rrstn)
        wptr_syn <= {(ADDR_WIDTH+1){1'b0}};
    else
        wptr_syn <= wptr_buff;
end
// Read pointer
always@(posedge rclk or negedge rrstn) begin
    if(!rrstn)
        raddr_bin <= {(ADDR_WIDTH+1){1'b0}};
    else if(rinc)
        raddr_bin <= raddr_bin + {{ADDR_WIDTH{1'b0}}, 1'b1};
end
assign rptr_gray = bin2gray(raddr_bin);
always@(posedge rclk or negedge rrstn) begin
    if(!rrstn)
        rptr <= {(ADDR_WIDTH+1){1'b0}};
    else
        rptr <= rptr_gray;
end
always@(posedge rclk or negedge rrstn) begin
    if(!rrstn)
        rptr_buff <= {(ADDR_WIDTH+1){1'b0}};
    else
        rptr_buff <= rptr;
end
always@(posedge wclk or negedge wrstn) begin
    if(!wrstn)
        rptr_syn <= {(ADDR_WIDTH+1){1'b0}};
    else
        rptr_syn <= rptr_buff;
end
// Full and empty signals
assign wfull = (wptr == {~rptr_syn[ADDR_WIDTH:ADDR_WIDTH-1], rptr_syn[ADDR_WIDTH-2:0]});
assign rempty = (rptr == wptr_syn);
endmodule
